/** Wavefront OBJ + MTL writer. Keeps the original quad topology; textures referenced from `texDir`. */
import type { MeshData } from '../core/mesh';
import { hexToRgb, srgbToLinear } from '../core/math';

const f = (x: number) => (Math.abs(x) < 1e-7 ? '0' : x.toFixed(6).replace(/\.?0+$/, ''));

export function exportOBJ(mesh: MeshData, name: string, mtlFile: string, texDir = 'textures/'): { obj: string; mtl: string } {
  const lines: string[] = [
    '# Generated by Ara 3D Gen character generator',
    `# ${mesh.positions.length / 3} vertices`,
    `mtllib ${mtlFile}`,
    `o ${name}`,
  ];
  const P = mesh.positions, N = mesh.normals, T = mesh.uvs;
  for (let i = 0; i < P.length; i += 3) lines.push(`v ${f(P[i])} ${f(P[i + 1])} ${f(P[i + 2])}`);
  for (let i = 0; i < T.length; i += 2) lines.push(`vt ${f(T[i])} ${f(T[i + 1])}`);
  for (let i = 0; i < N.length; i += 3) lines.push(`vn ${f(N[i])} ${f(N[i + 1])} ${f(N[i + 2])}`);
  for (const g of mesh.groups) {
    const m = mesh.materials[g.material];
    lines.push(`g ${name}_${m.name}`, `usemtl ${m.name}`, 's 1');
    for (let p = 0, c = 0; p < g.polySizes.length; p++) {
      const n = g.polySizes[p];
      let line = 'f';
      for (let k = 0; k < n; k++) {
        const v = g.polyIndices[c + k] + 1;
        line += ` ${v}/${v}/${v}`;
      }
      lines.push(line);
      c += n;
    }
  }

  const mtl: string[] = ['# Generated by Ara 3D Gen character generator'];
  for (const m of mesh.materials) {
    const [r, g, b] = hexToRgb(m.color).map(srgbToLinear);
    const ns = Math.round((1 - m.roughness) ** 2 * 900 + 4);
    mtl.push('', `newmtl ${m.name}`, 'Ka 0 0 0', `Kd ${f(r)} ${f(g)} ${f(b)}`, 'Ks 0.04 0.04 0.04', `Ns ${ns}`,
      `Pr ${f(m.roughness)}`, `Pm ${f(m.metalness)}`, `d ${f(m.opacity ?? 1)}`, 'illum 2');
    if (m.emissive) {
      const [er, eg, eb] = hexToRgb(m.emissive).map(srgbToLinear);
      mtl.push(`Ke ${f(er)} ${f(eg)} ${f(eb)}`);
    }
    if (m.map) mtl.push(`map_Kd ${texDir}${m.map}`);
    if (m.map && m.alpha !== 'opaque') mtl.push(`map_d ${texDir}${m.map}`);
    if (m.normalMap) mtl.push(`map_Bump -bm 1.0 ${texDir}${m.normalMap}`);
  }
  return { obj: lines.join('\n') + '\n', mtl: mtl.join('\n') + '\n' };
}
